insert into public.settings (key, value, is_public) values ('home', '{"heroTitle":"Vos plus beaux moments méritent une invitation unique.","heroSubtitle":"Des invitations digitales élégantes, interactives et personnalisées, pensées pour annoncer vos événements et partager chaque détail avec vos invités.","faq":[{"question":"Comment fonctionne une invitation digitale ?","answer":"C''est un mini-site pensé pour le téléphone, accessible par un simple lien. Vos invités y retrouvent le programme, les lieux, le dress code, un compte à rebours et le formulaire de réponse."},{"question":"Puis-je modifier les informations après publication ?","answer":"Oui. Nous mettons à jour votre invitation et le lien reste identique : vos invités voient toujours la dernière version validée."},{"question":"Comment partager l''invitation ?","answer":"Vous recevez un lien personnalisé (par exemple e-invitly.com/vos-prenoms) à envoyer par message, e-mail ou réseaux sociaux."},{"question":"Les invités doivent-ils créer un compte ?","answer":"Non. Ils ouvrent le lien et répondent directement, sans inscription ni application à télécharger."},{"question":"Comment recevoir les réponses RSVP ?","answer":"Chaque réponse est enregistrée dans votre espace personnel sécurisé, accessible par un lien de connexion envoyé par e-mail. Vous pouvez y suivre les présents, les accompagnants et exporter la liste."},{"question":"Puis-je utiliser mon propre texte ?","answer":"Bien sûr : le formulaire de personnalisation vous permet de nous transmettre vos textes, que nous intégrons au modèle choisi."},{"question":"Combien de temps mon invitation reste-t-elle disponible ?","answer":"La durée de mise en ligne vous est précisée lors de la validation de votre demande."}]}'::jsonb, true) on conflict (key) do nothing;
